{"chunk_id":"R5-211106-001","collection":"ran5_tdoc_chunks","metadata":{"source":["ZTE"],"tdocNumber":"R5-211106","title":"Discussion on subclause drafting rules in RAN5 specs"},"point_id":"7838427974658968563"}
